0.sql:
SELECT `주소` 
FROM `BLOCKED_SITE` 
WHERE `주소` LIKE '%kakao%';

SELECT COUNT(*) AS 단말기_개수
FROM INFO_SYS
WHERE `종류` = '서버';

SELECT `관리번호`, `모델명`
FROM `INFO_SYS`
WHERE `제조사` = 'Lenovo';

SELECT COUNT(*) AS 단말기_개수
FROM INFO_SYS
WHERE 도입년도 < '2020';

SELECT COUNT(*) AS 단말기_개수
FROM INFO_SYS
WHERE 도입년도 >= '2020';

SELECT `설치위치` 
FROM DORM_AP_EXTENDER 
WHERE `호관` = '12';

SELECT COUNT(*) AS 단말기_개수
FROM DORM_AP_EXTENDER
WHERE 설치_날짜 LIKE '2025-03-%';

SELECT 사용호실, 단말기_개수
FROM ROOM_IP_COUNTS
WHERE 단말기_개수 >= 10;

SELECT `호관`
FROM BUILDING_IP_COUNTS
WHERE `호실_수` > 50;

SELECT `종류`, COUNT(*) AS 장비_수 
FROM INFO_SYS 
GROUP BY `종류`;

SELECT 장비명, COUNT(*) AS 설치_대수 
FROM DORM_AP_EXTENDER 
GROUP BY 장비명;

SELECT AVG(`단말기_개수`) AS 평균_단말기_개수
FROM ROOM_IP_COUNTS
ROUND(AVG(`단말기_개수`), 2);

SELECT `호관`
FROM BUILDING_IP_COUNTS
ORDER BY CAST(`IP가_부여된_단말기_수` AS SIGNED) DESC;

SELECT COUNT(*) AS 단말기_개수
FROM JOINTEST
JOIN INFO_SYS ON JOINTEST.관리번호 = INFO_SYS.관리번호;

SELECT COUNT(*) AS 단말기_개수
FROM ROOM_IP_COUNTS
WHERE 단말기_개수 > (SELECT AVG(단말기_개수) FROM ROOM_IP_COUNTS);

SELECT COUNT(*) 
FROM IP 
WHERE 사용기기 = 'PC';

SELECT `관리번호`, `비고` 
FROM JOINTEST 
WHERE `도입년도` = '2020';

